import XCTest
@testable import Notes

private final class TestableSyncEngine: SyncEngine {
    var mergedResult: [Note] = []
    override func merge(local: [Note], remote: [Note]) -> [Note] { mergedResult }
}

final class SyncEngineMergeTests: XCTestCase {
    func testMergeKeepsNewestVersion() {
        let engine = TestableSyncEngine(store: InMemoryNoteStore())
        let newest = Note(id: "a", body: "v2", version: 2)
        engine.mergedResult = [newest]

        let merged = engine.merge(local: [Note(id: "a", body: "v1", version: 1)], remote: [newest])

        XCTAssertEqual(merged, [newest])
    }
}

import XCTest
@testable import Inventory

final class StockLedgerTests: XCTestCase {
    var ledger: StockLedger!

    override func setUp() {
        super.setUp()
        ledger = StockLedger()
    }

    func testReceiveIncreasesOnHand() {
        ledger.receive(sku: "A-1", quantity: 10)
        XCTAssertEqual(ledger.onHand(sku: "A-1"), 10)
    }

    func testShipDecreasesOnHand() throws {
        ledger.receive(sku: "A-1", quantity: 10)
        try ledger.ship(sku: "A-1", quantity: 3)
        XCTAssertEqual(ledger.onHand(sku: "A-1"), 7)
    }

    func testShipMoreThanOnHandIsRejected() {
        ledger.receive(sku: "A-1", quantity: 2)
        _ = try? ledger.ship(sku: "A-1", quantity: 5)
    }

    func testHistoryIsChronological() {
        ledger.receive(sku: "A-1", quantity: 1)
        ledger.receive(sku: "A-1", quantity: 2)
        XCTAssertEqual(ledger.history(sku: "A-1").map(\.quantity), [1, 2])
    }
}

