        try await mailer.send(to: order.email, subject: subject, body: body)
    }
}

import Foundation

final class URLProtocolStub: URLProtocol {
    private static var stub: (data: Data?, response: HTTPURLResponse?, error: Error?)?

    static func stub(data: Data, statusCode: Int) {
        let response = HTTPURLResponse(url: URL(string: "https://example.com")!, statusCode: statusCode, httpVersion: nil, headerFields: nil)
        stub = (data, response, nil)
    }

    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        if let error = Self.stub?.error { client?.urlProtocol(self, didFailWithError: error) }
        if let response = Self.stub?.response { client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed) }
        if let data = Self.stub?.data { client?.urlProtocol(self, didLoad: data) }
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}

